mapper.sql:
WHERE c.workspace_id = #{q.workspaceId} AND c.req_id = #{q.reqId}
AND c.latest_status IS NULL AND c.latest_status = #{q.status}
AND c.module_id IS NULL
AND c.module_id IN #{mid}
AND (c.module IS NULL OR c.module = '') AND c.module = #{q.module}
AND (c.priority IS NULL OR c.priority = '') AND c.priority = #{q.pri}
AND (c.latest_by IS NULL OR c.latest_by = '')
AND c.latest_by = #{q.owner}
AND c.demand_id IS NULL AND c.demand_id = #{q.demandId}
AND NOT EXISTS (SELECT 1 FROM case_set_item si JOIN case_set s ON s.id = si.set_id AND s.workspace_id = si.workspace_id WHERE si.case_id = c.id AND (s.visibility = 'team' OR s.owner_user_id = #{q.viewerId} OR EXISTS (SELECT 1 FROM case_set_member sm WHERE sm.set_id = s.id AND sm.user_id = #{q.viewerId})))
AND EXISTS (SELECT 1 FROM case_set_item si WHERE si.case_id = c.id AND si.set_id IN #{sid})
AND EXISTS (SELECT 1 FROM case_set_item si WHERE si.case_id = c.id AND si.set_id = #{q.setId})
AND
AND (c.latest_status IN ('failed', 'blocked') OR )
AND (c.title LIKE CONCAT('%', #{q.q}, '%') OR c.precondition LIKE CONCAT('%', #{q.q}, '%') OR c.test_data LIKE CONCAT('%', #{q.q}, '%') OR c.module LIKE CONCAT('%', #{q.q}, '%') OR c.latest_note LIKE CONCAT('%', #{q.q}, '%') OR c.steps LIKE CONCAT('%', #{q.q}, '%') OR d.title LIKE CONCAT('%', #{q.q}, '%') OR t.title LIKE CONCAT('%', #{q.q}, '%') OR c.case_no = #{q.caseNo} )
AND (c.title LIKE CONCAT('%', #{q.q}, '%') OR c.module LIKE CONCAT('%', #{q.q}, '%') OR c.case_no = #{q.caseNo} )
AND c.id NOT IN #{eid}

