SELECT * FROM test_case
WHERE workspace_id = #{workspaceId}
  AND id IN
  #{id}

SELECT id FROM test_case
WHERE workspace_id = #{workspaceId} AND req_id = #{reqId}


   AND module_id IS NULL 
   AND module_id = #{moduleId} 

ORDER BY sort_order, created_at, id

SELECT 'case' AS type, c.id, c.title, c.req_id AS reqId, r.name AS reqName, c.latest_status AS status, c.module AS extra, c.case_no AS caseNo, c.updated_at AS updatedAt FROM test_case c LEFT JOIN requirement r ON r.id = c.req_id AND r.workspace_id = c.workspace_id WHERE c.workspace_id = #{workspaceId} AND ( LOCATE(LOWER(#{q}), LOWER(c.title)) > 0 OR LOCATE(LOWER(#{q}), LOWER(c.module)) > 0 OR LOCATE(LOWER(#{q}), LOWER(c.precondition)) > 0 OR c.case_no = #{caseNo} )
AND NOT EXISTS (SELECT 1 FROM project_member pm WHERE pm.workspace_id = c.workspace_id AND pm.project_id = c.req_id AND pm.user_id = #{viewerId} AND pm.access = 'none')
ORDER BY c.updated_at DESC LIMIT #{limit}

